const lavaGiantSheet=new Image();lavaGiantSheet.assetSrc='assets/lava-giant-v2.png';
function beginLavaGiant(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'lavaExpandingQuake',bespoke:true,windup:1.6,origin:{x:e.x,y:e.y},slammed:false,hit:false};}
function lavaQuakeRadius(time){return 130+200*Math.max(0,Math.min(1.2,time-1.6));}
function lavaQuakeTouches(a,point,from,to){if(to<1.6||from>2.8)return false;let d=dist(a.origin,point);return d>=lavaQuakeRadius(Math.max(from,1.6))-18-1e-8&&d<=lavaQuakeRadius(Math.min(to,2.8))+18+1e-8;}
const lavaGiantAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r7e4')return lavaGiantAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='lavaExpandingQuake'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginLavaGiant(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.7;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,54*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,28)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.slammed&&e.elapsed>=1.6){a.slammed=true;e.struck=true;if(dist(p,a.origin)<=130+1e-8&&lineClear(a.origin,p)&&!(p.inv>0)){a.hit=true;hurt(96);}burst(e.x,e.y,130,'#ffb56a');playSound('impact',e.x,e.y);}
 if(!dead&&!a.hit&&!(p.inv>0)&&lavaQuakeTouches(a,p,before,e.elapsed)&&lineClear(a.origin,p)){a.hit=true;hurt(72);}
 if(e.elapsed>=3.6){e.attack=null;e.state='idle';e.t=3;}
};
const lavaGiantDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r7e4'||!lavaGiantSheet.complete||!lavaGiantSheet.naturalWidth||!lavaGiantSheet.naturalHeight)return lavaGiantDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='lavaExpandingQuake')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.6?1:e.elapsed<1.9?2:3};let q=project(e.x,e.y),sw=lavaGiantSheet.naturalWidth/4,sh=lavaGiantSheet.naturalHeight/3,w=340,h=w*sh/sw,anchor=[.85,.8,.8][f.row];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,lavaGiantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(lavaGiantSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const lavaGiantSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r7e4'?220:lavaGiantSizeBase(e);
const lavaGiantGroundBase=drawGroundEffects;drawGroundEffects=()=>{lavaGiantGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r7e4'):enemies)){let a=e.attack;if(e.species!=='r7e4'||e.hp<=0||a?.pattern!=='lavaExpandingQuake'||!visibleAt(e.x,e.y))continue;if(e.elapsed<1.6){groundRing(e.x,e.y,130,'#ffac72',2);groundRing(e.x,e.y,388,'#c7774933',1);}else if(e.elapsed<=2.8){let r=lavaQuakeRadius(e.elapsed),q=project(e.x,e.y);ctx.save();ctx.translate(q.x,q.y);ctx.transform(ISOX,ISOY,-ISOX,ISOY,0,0);ctx.fillStyle=a.hit?'#d7874c22':'#ff963c55';ctx.strokeStyle=a.hit?'#b57f55':'#ffcf86';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,r+18,0,Math.PI*2);ctx.arc(0,0,r-18,Math.PI*2,0,true);ctx.closePath();ctx.fill();ctx.stroke();ctx.restore();}else groundRing(e.x,e.y,45,'#9bddcf',2);}};
